detail.command:
set -euo pipefail
ROOT="$PWD"
TMP="$(mktemp -d /tmp/delete2-rn.XXXXXX)"
cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT

printf '%s\n' '--- create React Native template ---'
npx --yes @react-native-community/cli@latest init Delete2 --directory "$TMP/app" --skip-git-init --skip-install

printf '%s\n' '--- copy scaffold while preserving Cornel technical files ---'
rsync -a --exclude '.git' --exclude '.cornel' --exclude 'AGENTS.md' "$TMP/app/" "$ROOT/"

mkdir -p src/screens src/components src/services src/types

cat > src/types/market.ts <<'EOF'
export interface MarketAsset {
  id: string;
  symbol: string;
  name: string;
}

export interface MarketQuote {
  assetId: MarketAsset['id'];
  currency: string;
  price: number;
  change24hPercent: number;
  updatedAt: string;
}

export type MarketRecommendationAction = 'buy' | 'hold' | 'avoid';

export interface MarketRecommendation {
  assetId: MarketAsset['id'];
  action: MarketRecommendationAction;
  confidence: number;
  rationale: string;
  generatedAt: string;
}
EOF

cat > src/types/index.ts <<'EOF'
export * from './market';
EOF

cat > src/services/index.ts <<'EOF'
export interface MarketDataService {
  getLatestQuotes(): Promise<unknown>;
}
EOF

cat > src/components/SectionCard.tsx <<'EOF'
import React, {PropsWithChildren} from 'react';
import {StyleSheet, Text, View} from 'react-native';

type SectionCardProps = PropsWithChildren<{
  title: string;
}>;

export function SectionCard({title, children}: SectionCardProps) {
  return (
    <View style={styles.card}>
      <Text style={styles.title}>{title}</Text>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  card: {
    backgroundColor: '#17171d',
    borderRadius: 16,
    padding: 18,
    gap: 8,
  },
  title: {
    color: '#ffffff',
    fontSize: 18,
    fontWeight: '700',
  },
});
EOF

cat > src/components/index.ts <<'EOF'
export * from './SectionCard';
EOF

cat > src/screens/HomeScreen.tsx <<'EOF'
import React from 'react';
