cat > src/screens/index.ts <<'EOF'
export * from './HomeScreen';
EOF

cat > App.tsx <<'EOF'
import React from 'react';
import {StatusBar, useColorScheme} from 'react-native';
import {HomeScreen} from './src/screens';

export default function App() {
  const isDarkMode = useColorScheme() === 'dark';

  return (
    <>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} />
      <HomeScreen />
    </>
  );
}
EOF

cat > __tests__/marketTypes.test.ts <<'EOF'
import type {MarketAsset, MarketQuote, MarketRecommendation} from '../src/types';

describe('market contracts', () => {
  it('allow a consistent asset, quote and recommendation model', () => {
    const asset: MarketAsset = {id: 'bitcoin', symbol: 'BTC', name: 'Bitcoin'};
    const quote: MarketQuote = {
      assetId: asset.id,
      currency: 'USD',
      price: 100000,
      change24hPercent: 1.25,
      updatedAt: '2026-09-16T00:00:00.000Z',
    };
    const recommendation: MarketRecommendation = {
      assetId: asset.id,
      action: 'hold',
      confidence: 0.5,
      rationale: 'Test fixture',
      generatedAt: quote.updatedAt,
    };

    expect(quote.assetId).toBe(asset.id);
    expect(recommendation.assetId).toBe(asset.id);
  });
});
EOF

node -e "const fs=require('fs');const p=JSON.parse(fs.readFileSync('package.json','utf8'));p.scripts={...p.scripts,typecheck:'tsc --noEmit'};fs.writeFileSync('package.json',JSON.stringify(p,null,2)+'\n')"

printf '%s\n' '--- install dependencies ---'
npm install

printf '%s\n' '--- typecheck ---'
npm run typecheck

printf '%s\n' '--- tests ---'
npm test -- --runInBand

printf '%s\n' '--- final status ---'
git status --short
